from taf.ul.power_ue.available_devices import SupportedPowerUeDevices


def create_device(ue_selector, tl, ue_config, robot_logs_dir, **kwargs):
    """
    create device object according to the device type and model.

    :param str ue_selector: ue solution, e.g. fastmile.
    :param object tl: testline configuration instance.
    :param object ue_config: testline configuration ue instance.
    :param str robot_logs_dir: logs folder for robot.
    :return: object of PowerUeDevices subclass
    """
    device_cls = SupportedPowerUeDevices.lookup_device(ue_selector)
    return device_cls(
        tl=tl, ue_config=ue_config, robot_logs_dir=robot_logs_dir, **kwargs
    )
